import os, base64, zlib
R = "LockCOC" if os.path.isdir("LockCOC") else "."
def P(p): return os.path.join(R, p)
def rd(p): return open(P(p), encoding="utf-8").read()
def w(p, s): open(P(p), "w", encoding="utf-8").write(s)
F = {'srv.py': '', 'lib27.js': '', 'cam27.js': '', 'x27.css': ''}
def D(k): return zlib.decompress(base64.b64decode(F[k])).decode("utf-8")
def sub(s, old, new, what):
    if old not in s: raise SystemExit("[loi] khong thay doan can sua: " + what)
    return s.replace(old, new, 1)
a = rd("app.py")
if "delete-many" in a: raise SystemExit("[loi] da ap dung patch27 roi")
a = sub(a, '@app.get("/library")', D("srv.py") + '\n\n\n@app.get("/library")', "route library")
a = sub(a, '    q("DELETE FROM posts WHERE key=? AND moment_uid=?", (e.key, mid), commit=True)\n    return jr({"ok": True})',
        '    q("DELETE FROM posts WHERE key=? AND moment_uid=?", (e.key, mid), commit=True)\n    q("DELETE FROM sync_items WHERE key=? AND mid=?", (e.key, mid), commit=True)\n    return jr({"ok": True})', "xoa don")
w("app.py", a)
L = rd("static/js/library.js")
L = sub(L, 'b.addEventListener("click", function () { open(m); });\n    return b;',
        'b.dataset.id = m.id; b.dataset.mine = m.mine ? "1" : "0";\n    b.addEventListener("click", function () { if (SEL.on) pick(b, m); else open(m); });\n    return b;', "tile")
L = sub(L, 'function open(m) {\n', 'function open(m) {\n    cur = m; viewDel.classList.toggle("hidden", !m.mine);\n', "open")
L = sub(L, '  function tile(m) {', D("lib27.js") + '\n  function tile(m) {', "chen")
w("static/js/library.js", L)
w("static/js/cam27.js", D("cam27.js"))
c = rd("static/polish.css"); w("static/polish.css", c + "\n" + D("x27.css"))
lc = rd("static/library.css"); w("static/library.css", lc + "\n" + D("x27.css"))
h = rd("templates/index.html")
h = sub(h, '  <script src="/static/js/camera.js"></script>', '  <script src="/static/js/camera.js"></script>\n  <script src="/static/js/cam27.js"></script>', "index script")
w("templates/index.html", h)
print("[ok] patch27 xong")
